#include <bits/stdc++.h>
using namespace std;using M=uint32_t;constexpr M FULL=(1u<<26)-1;const vector<string> morse={".-","-...","-.-.","-..",".","..-.","--.","....","..",".---","-.-",".-..","--","-.","---",".--.","--.-",".-.","...","-","..-","...-",".--","-..-","-.--","--.."};
struct Word{string w,c;double sc;};struct Arc{int end,word;double sc;vector<pair<int,M>> req;};struct State{array<M,26>d;double sc;int parent,arc;};struct Node{int prev,pos,arc;};
struct Beam{vector<State> v;size_t cap;static bool cmp(const State&a,const State&b){return a.sc>b.sc;}void push(State s){if(v.size()<cap){v.push_back(move(s));push_heap(v.begin(),v.end(),cmp);}else if(s.sc>v.front().sc){pop_heap(v.begin(),v.end(),cmp);v.back()=move(s);push_heap(v.begin(),v.end(),cmp);}}};
int trit(char c){return c=='.'?0:c=='-'?1:2;}
int main(int argc,char**argv){if(argc<4)return 1;int width=stoi(argv[3]),lexlimit=argc>4?stoi(argv[4]):5000;ifstream in(argv[1]);vector<pair<string,int>>raw;string w;int f;while(in>>w>>f)raw.push_back({w,f});sort(raw.begin(),raw.end(),[](auto&a,auto&b){return a.second!=b.second?a.second>b.second:a.first<b.first;});raw.resize(min<int>(raw.size(),lexlimit));double z=0;for(auto&x:raw)z+=x.second;
vector<Word>words;for(auto&[x,c]:raw){if(x.size()==1&&x!="a"&&x!="i")continue;string s;for(char l:x){if(!s.empty())s+='x';s+=morse[l-'a'];}s+="xx";words.push_back({x,s,log(c/z)});}
vector<string>book;for(char a:string(".-x"))for(char b:string(".-x"))for(char c:string(".-x"))if(a!='x'||b!='x'||c!='x')book.push_back({a,b,c});M tm[3][3]{};for(int k=0;k<26;k++)for(int j=0;j<3;j++)tm[j][trit(book[k][j])]|=1u<<k;
ifstream ti(argv[2]);vector<int>t;int x;while(ti>>x)t.push_back(x);set<int>ss(t.begin(),t.end());vector<int>types(ss.begin(),ss.end());for(auto&v:t)v=lower_bound(types.begin(),types.end(),v)-types.begin();int N=types.size(),L=3*t.size();assert(N<=26);vector<vector<Arc>>arcs(L);size_t na=0;
auto consistent=[&](array<M,26>&d){M used=0,prev;do{prev=used;used=0;for(int i=0;i<N;i++){M m=d[i];if(!m)return false;if(!(m&(m-1))){if(used&m)return false;used|=m;}}for(int i=0;i<N;i++)if(d[i]&(d[i]-1)){d[i]&=~used;if(!d[i])return false;}}while(prev!=used);return true;};
for(int p=0;p<L;p++){auto&a=arcs[p];unordered_set<string>clipped;for(int wi=0;wi<(int)words.size();wi++){auto&ww=words[wi];int len=min<int>(ww.c.size(),L-p),end=p+len;if(end==L&&len<(int)ww.c.size()&&!clipped.insert(ww.c.substr(0,len)).second)continue;array<M,26>d;d.fill(FULL);M touched=0;bool good=true;for(int j=0;j<len;j++){int q=p+j,u=t[q/3];d[u]&=tm[q%3][trit(ww.c[j])];touched|=1u<<u;if(!d[u]){good=false;break;}}if(!good||!consistent(d))continue;Arc e{end,wi,ww.sc,{}};for(int u=0;u<N;u++)if(touched&(1u<<u))e.req.push_back({u,d[u]});a.push_back(move(e));}sort(a.begin(),a.end(),[](auto&a,auto&b){return a.sc>b.sc;});na+=a.size();}
if(argc>5&&stoi(argv[5])){unordered_set<string>seen;for(int wi=0;wi<(int)words.size();wi++){auto&ww=words[wi];for(int cut=1;cut<(int)ww.c.size();cut++){string q=ww.c.substr(cut);int len=q.size();if(len>L||!seen.insert(q).second)continue;array<M,26>d;d.fill(FULL);M touched=0;bool good=true;for(int j=0;j<len;j++){int u=t[j/3];d[u]&=tm[j%3][trit(q[j])];touched|=1u<<u;if(!d[u]){good=false;break;}}if(!good||!consistent(d))continue;Arc e{len,wi,ww.sc,{}};for(int u=0;u<N;u++)if(touched&(1u<<u))e.req.push_back({u,d[u]});arcs[0].push_back(move(e));na++;}}sort(arcs[0].begin(),arcs[0].end(),[](auto&a,auto&b){return a.sc>b.sc;});}
cerr<<"types="<<N<<" trits="<<L<<" lex="<<words.size()<<" arcs="<<na<<" width="<<width<<endl;int start=argc>6?stoi(argv[6]):0;vector<Beam>beams(L+1);for(auto&b:beams)b.cap=width;State init;init.d.fill(FULL);init.sc=0;init.parent=-1;init.arc=-1;beams[start].push(init);vector<Node>path;uint64_t tried=0,ok=0;int last=0;
for(int p=start;p<L;p++){auto&states=beams[p].v;if(states.empty())continue;last=p;if(p%24==0)cerr<<"p="<<p<<" beam="<<states.size()<<" tried="<<tried<<" ok="<<ok<<endl;for(auto&st:states){int node=path.size();path.push_back({st.parent,p,st.arc});for(int ai=0;ai<(int)arcs[p].size();ai++){auto&a=arcs[p][ai];auto&b=beams[a.end];double sc=st.sc+a.sc;if(b.v.size()==b.cap&&sc<=b.v.front().sc)continue;tried++;bool good=true;for(auto[u,m]:a.req)if(!(st.d[u]&m)){good=false;break;}if(!good)continue;State ns=st;for(auto[u,m]:a.req)ns.d[u]&=m;if(!consistent(ns.d))continue;ok++;ns.sc=sc;ns.parent=node;ns.arc=ai;b.push(move(ns));}}vector<State>().swap(states);}
cerr<<"tried="<<tried<<" accepted="<<ok<<" last="<<last<<" final="<<beams[L].v.size()<<endl;auto&end=beams[L].v;if(start){vector<State>complete;for(auto&st:end)for(auto&a:arcs[0])if(a.end==start){State ns=st;bool good=true;for(auto[u,m]:a.req){ns.d[u]&=m;if(!ns.d[u]){good=false;break;}}if(good&&consistent(ns.d)){ns.sc+=a.sc;complete.push_back(move(ns));}}end.swap(complete);cerr<<"prefix-complete="<<end.size()<<endl;}sort(end.begin(),end.end(),[](auto&a,auto&b){return a.sc>b.sc;});for(int q=0;q<min<int>(5,end.size());q++){auto&st=end[q];vector<string>out;int parent=st.parent,arc=st.arc;while(parent>=0){auto pn=path[parent];out.push_back(words[arcs[pn.pos][arc].word].w);arc=pn.arc;parent=pn.prev;}reverse(out.begin(),out.end());cout<<"score="<<st.sc<<" ";for(auto&w:out)cout<<w<<' ';cout<<"\nkey=";for(int i=0;i<N;i++){M m=st.d[i];cout<<types[i]<<":"<<(m&&(m&(m-1))==0?book[__builtin_ctz(m)]:"?")<<",";}cout<<"\n";}}
